configuration.tbelDecoder:
/** Decoder **/

var data = decodeToJson(payload);

// Caso 1: messaggio di test con wrapper:
// {
//   "topic": "...",
//   "payload": {...}
// }
//
// Caso 2: payload reale diretto:
// {
//   "device_id": "sensore_001",
//   "analysis": {...},
//   "hw": {...}
// }

var p = {};

if (data && data.payload) {
    p = data.payload;
} else if (data) {
    p = data;
}

// Nome dispositivo
var deviceName = p.device_id ? String(p.device_id) : 'sensore_001';
var deviceType = 'Optical Biosensor';

// Sotto-oggetti
var hw = p.hw || {};
var analysis = p.analysis || {};
var ram = hw.ram || {};
var disk = hw.disk || {};

// Funzioni sicure
function toNumber(value, defaultValue) {
    if (value === undefined || value === null || value === '') {
        return defaultValue;
    }

    var n = Number(value);
    if (isNaN(n)) {
        return defaultValue;
    }

    return n;
}

function toBoolNumber(value) {
    return value === true ? 1 : 0;
}

var result = {
    deviceName: deviceName,
    deviceType: deviceType,

    attributes: {
        sample_id: p.sample_id ? String(p.sample_id) : ''
    },

    telemetry: {
        spore_count: toNumber(analysis.spore_count, 0),
        detected: toBoolNumber(analysis.detected),
        frame_id: toNumber(p.frame_id, 0),
        cpu_temp_c: toNumber(hw.cpu_temp_c, 0),
        processing_time_s: toNumber(hw.processing_time_s, 0),
        ram_used_percent: toNumber(ram.used_percent, 0),
        disk_used_percent: toNumber(disk.used_percent, 0),

        // Test rapido
        prova: toBoolNumber(p.prova)
    }
};

return result;
